public void written()
{
    FormRun             formRun = this.formRun();
    FormDataSource      custInvTableDS = formRun.dataSource(tableStr(CustInvoiceTable));
    CustInvoiceTable    prevCustInvoiceTable = custInvTableDS.cursor();
    CustInvoiceLine      prevCustInvoiceLine = this.cursor();                
    next written();

    custInvTableDS.reread();
    custInvTableDS.refresh();

    //this.positionToRecord(prevCustInvoiceLine);      
}

/// <summary>
/// N.Freidenberger 23.09.2024
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = next active();

    CustInvoiceLine locCustInvoiceLine;
    FormControl     locFC_AVABonusAlliance;
    FormControl     locFC_AVABonusCustAccount;
    boolean         locAllowEdit_AVABonusAlliance;


    locCustInvoiceLine = element.dataSource(tableStr(CustInvoiceLine)).cursor();

    if(locCustInvoiceLine.AVABonusAllocationBase == AVABonusAllocationBase::Customer)
    {
        locAllowEdit_AVABonusAlliance = false;
    }
    else if(locCustInvoiceLine.AVABonusAllocationBase == AVABonusAllocationBase::Alliance)
    {
        locAllowEdit_AVABonusAlliance = true;
    }
    locFC_AVABonusAlliance     = element.design().controlName(formControlStr(CustFreeInvoice, LinesGridGroup_Bonus_AVABonusAlliance));
    locFC_AVABonusAlliance.allowEdit(locAllowEdit_AVABonusAlliance);
    locFC_AVABonusAlliance     = element.design().controlName(formControlStr(CustFreeInvoice, CVInvoiceDetailsTabPageGroup_BonusFields_AVABonusAlliance));
    locFC_AVABonusAlliance.allowEdit(locAllowEdit_AVABonusAlliance);

    locFC_AVABonusCustAccount     = element.design().controlName(formControlStr(CustFreeInvoice, LinesGridGroup_Bonus_AVABonusCustAccount));
    locFC_AVABonusCustAccount.allowEdit(!locAllowEdit_AVABonusAlliance);
    locFC_AVABonusCustAccount     = element.design().controlName(formControlStr(CustFreeInvoice, CVInvoiceDetailsTabPageGroup_BonusFields_AVABonusCustAccount));
    locFC_AVABonusCustAccount.allowEdit(!locAllowEdit_AVABonusAlliance);

    return ret;
}
